import { SUPABASE_URL, SUPABASE_ANON_KEY } from './config.js';

/* Willa's Little Wins — local-first mobile prototype; optional Supabase household sync. */
const QUESTS = [
  {id:'den',emoji:'🏡',title:'The Cozy Den',short:'Make the crate a place she chooses.',category:'Crate',steps:[
    'Leave the crate door open. Scatter or toss a few treats near the doorway, then inside if Willa wants to follow.',
    'Let Willa come and go. Praise a sniff, a voluntary step inside, or a relaxed pause. No luring her in and then shutting the door.',
    'If she is already happily entering and relaxing, you can practise touching or briefly moving the door, returning to open-door play whenever she seems unsure.'
  ],success:'An easy, voluntary interaction with a loose body and no hesitation.',guard:'If she avoids the crate or becomes watchful, make the game easier. Crate time and alone time are separate skills.'},
  {id:'cues',emoji:'🗝️',title:'Keys Are Boring',short:'Make getting ready less dramatic.',category:'Departure cues',steps:[
    'Pick one everyday leaving cue, such as picking up keys, putting on shoes, or reaching for a coat.',
    'Do that one thing, then carry on with normal life rather than leaving. Keep the cue mild enough that Willa stays comfortable.',
    'Repeat casually at different times. If she starts anticipating a departure, go back to an easier version.'
  ],success:'Willa stays relaxed or quickly returns to what she was doing.',guard:'This is not a test: don’t escalate to a full departure just because she managed one cue.'},
  {id:'blink',emoji:'🚪',title:'Back in a Flash',short:'A tiny, comfortable disappearance.',category:'Alone practice',steps:[
    'Choose the easiest setup: perhaps step just out of sight behind an interior door while Willa is already relaxed. Record whether the other person is home if useful.',
    'Return while she is still comfortable. The first repetition may be one second or less; that is fine.',
    'Wait until she has fully relaxed again before repeating. If you notice worry, next time use a much shorter or easier disappearance.'
  ],success:'She remains comfortable during the absence and your return.',guard:'Do not leave her to cry it out or use a closed crate for this unless she already finds the crate relaxing.'},
  {id:'wait',emoji:'👟',title:'The Waiting Game',short:'One human steps away, one stays.',category:'Out-and-about',steps:[
    'Start somewhere familiar and quiet. One of you stays with Willa while the other takes just a step or two away.',
    'The person who walked away returns before Willa gets upset. The person staying simply keeps things calm and ordinary.',
    'Try tiny variations only when the current version is easy. This can eventually apply to short shop-door separations.'
  ],success:'She can notice the departing person and remain settled.',guard:'If she is panting, pulling, vocalizing, or struggling to settle, shorten the distance and make it easier.'}
];
const PETS = [{id:'Willa',emoji:'🐶',subtitle:'Chief adventure officer'},{id:'Oscar',emoji:'🐈',subtitle:'Senior consultant'},{id:'Dennis',emoji:'🐈‍⬛',subtitle:'Director of loafing'}];
const STICKERS = [{id:'⭐',label:'Gold star'},{id:'💖',label:'Heart'},{id:'🐾',label:'Paw'},{id:'🌼',label:'Daisy'},{id:'💩',label:'Poop'},{id:'✨',label:'Sparkle'}];
const MILESTONES=[{min:0,name:'Tiny Beginnings',emoji:'🌱'},{min:45,name:'First Brave Steps',emoji:'🐶'},{min:110,name:'Brave Little Bean',emoji:'🦴'},{min:210,name:'Paw-some Pair',emoji:'🐾'},{min:350,name:'Very Important Pets',emoji:'🏆'},{min:550,name:'Household Legends',emoji:'👑'}];
const UNLOCKS=[
  {min:45,code:'🐶',name:"Willa's Gold Star",note:'For brave little moments, big or small.'},
  {min:110,code:'🦴',name:'The Good Dog Biscuit',note:'Officially earned by the entire household.'},
  {min:210,code:'🐱',name:"Oscar's Approval",note:'A rare and precious endorsement.'},
  {min:350,code:'😼',name:"Dennis's Judgment",note:'He has reviewed your efforts. He has notes.'},
  {min:550,code:'🏅',name:'Household Heroes',note:'A medal for all three of them, plus the humans.'}
];
const earnedUnlocks=()=>UNLOCKS.filter(u=>score()>=u.min);
const newlyEarned=(before,after)=>UNLOCKS.find(u=>u.min>before &&u.min<=after);
const DEFAULT_PORTRAITS={Willa:'data:image/webp;base64,'};
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const uid=()=>globalThis.crypto?.randomUUID?.()||('local-'+Date.now()+'-'+Math.random().toString(36).slice(2));
const fmt=d=>new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const ago=d=>{let h=(Date.now()-new Date(d).getTime())/3600000;return h<16?'Today':h<40?'Yesterday':fmt(d)};
const app=document.getElementById('app');
const CLOUD=!!(SUPABASE_URL && SUPABASE_ANON_KEY);
const state={mode:CLOUD?'cloud':'local',tab:'home',modal:null,actor:localStorage.getItem('willa-actor')||'Hil',logs:[],assets:[],supabase:null,user:null,household:null,member:null,sub:null,notice:null,assetUrls:new Map()};

function idb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('willa-little-wins-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('photos');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function blobPut(id,blob){const db=await idb();return new Promise((res,rej)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').put(blob,id);tx.oncomplete=()=>{db.close();res()};tx.onerror=()=>rej(tx.error)})}
async function blobGet(id){const db=await idb();return new Promise((res,rej)=>{const tx=db.transaction('photos');const req=tx.objectStore('photos').get(id);req.onsuccess=()=>{db.close();res(req.result)};req.onerror=()=>rej(req.error)})}
function persistLocal(){localStorage.setItem('willa-logs',JSON.stringify(state.logs));localStorage.setItem('willa-assets',JSON.stringify(state.assets))}
function loadLocal(){try{state.logs=JSON.parse(localStorage.getItem('willa-logs')||'[]');state.assets=JSON.parse(localStorage.getItem('willa-assets')||'[]')}catch{state.logs=[];state.assets=[]}}
async function maybeInitCloud(){if(!CLOUD){loadLocal();await render();return}try{const lib=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');state.supabase=lib.createClient(SUPABASE_URL,SUPABASE_ANON_KEY);const {data:{session}}=await state.supabase.auth.getSession();if(session){state.user=session.user;await loadMembership()}else renderAuth();state.supabase.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){state.user=null;state.household=null;state.member=null;renderAuth()}else if(event==='SIGNED_IN'&&session?.user&&!state.user){state.user=session.user;setTimeout(loadMembership,0)}})}catch(e){app.innerHTML=`<div class="login"><h1>Could not connect</h1><p>${esc(e.message)}</p><p>Check your Supabase settings in config.js and internet connection.</p></div>`}}
async function loadMembership(){const {data,error}=await state.supabase.from('memberships').select('household_id,display_name').eq('user_id',state.user.id).maybeSingle();if(error){toast(error.message);return}if(!data){state.member=null;renderJoin();return}state.member=data;state.actor=data.display_name;const house=await state.supabase.from('households').select('id,name,invite_code').eq('id',data.household_id).single();if(house.error){toast(house.error.message);return}state.household=house.data;await loadCloud();if(state.sub)state.supabase.removeChannel(state.sub);state.sub=state.supabase.channel('willa-household-'+state.household.id).on('postgres_changes',{event:'*',schema:'public',table:'entries',filter:'household_id=eq.'+state.household.id},()=>loadCloud()).on('postgres_changes',{event:'*',schema:'public',table:'assets',filter:'household_id=eq.'+state.household.id},()=>loadCloud()).subscribe()}
async function loadCloud(){if(!state.household)return;const [logs,assets]=await Promise.all([state.supabase.from('entries').select('*').eq('household_id',state.household.id).order('created_at',{ascending:false}),state.supabase.from('assets').select('*').eq('household_id',state.household.id).order('created_at',{ascending:false})]);if(logs.error||assets.error){toast((logs.error||assets.error).message);return}state.logs=logs.data;state.assets=assets.data;await render()}
function renderAuth(message=''){app.innerHTML=`<div class="login"><div style="font-size:70px">🐶</div><div class="little-label">A shared little world</div><h1>Willa's Little Wins</h1><p>Sign in with your own email to share the same scrapbook with each other.</p>${message?`<div class="auth-alert">${esc(message)}</div>`:''}<form id="auth-form"><input type="email" name="email" autocomplete="email" placeholder="you@example.com" aria-label="Your email" required><button class="main-btn wide">Email me a sign-in link</button></form></div>`}
function renderJoin(message=''){app.innerHTML=`<div class="login"><div style="font-size:58px">🏡</div><h1>Welcome to the household</h1><p>One of you creates the shared scrapbook, and the other joins with its code.</p>${message?`<div class="auth-alert">${esc(message)}</div>`:''}<form id="join-form"><div class="field"><label>Who's here?</label><select name="display_name"><option>Hil</option><option>Peter</option></select></div><div class="field"><label>Have a household code?</label><input name="invite_code" placeholder="Leave blank to create a household" maxlength="10" autocomplete="off"></div><button class="main-btn wide">Enter the little world</button></form><button data-action="sign-out" class="tiny-link spaced">Use a different email</button></div>`}
async function loadAssetUrls(){for(const a of state.assets){if(state.assetUrls.has(a.id))continue;try{if(state.mode==='local'){const blob=await blobGet(a.id);if(blob)state.assetUrls.set(a.id,URL.createObjectURL(blob))}else{const {data,error}=await state.supabase.storage.from('pet_media').createSignedUrl(a.path,3600);if(!error&&data)state.assetUrls.set(a.id,data.signedUrl)}}catch(e){console.warn('Photo unavailable',e)}}}
function assetUrl(id){return state.assetUrls.get(id)||''}
function portrait(name){return state.assets.find(a=>a.type==='portrait'&&a.pet_name===name)}
function defaultPortraitUrl(name){return DEFAULT_PORTRAITS[name]||''}
function portraitSource(name){const saved=portrait(name);return saved?assetUrl(saved.id):defaultPortraitUrl(name)}
function photoHero(){const src=portraitSource('Willa');return `<section class="photo-hero ${src?'':'hero-no-photo'}">${src?`<img class="hero-img" alt="Willa" src="${esc(src)}">`:`<div class="hero-fallback">🐶</div>`}<div class="hero-shade"></div><div class="hero-copy"><div class="little-label" style="color:inherit">For Willa, Oscar & Dennis</div><h2>Little wins. Big feelings.</h2><p>Good dogs, chaotic cats, and tiny brave moments.</p></div></section>`}
function score(){return state.logs.reduce((total,l)=>total+(l.actor==='Hil'? (l.comfort==='comfy'?14:l.comfort==='unsure'?7:4):(l.comfort==='comfy'?7:l.comfort==='unsure'?4:2)),0)+state.assets.filter(a=>a.type==='photo').reduce((total,a)=>total+(a.created_by_name==='Hil'?9:5),0)}
function level(){const points=score();let i=MILESTONES.findLastIndex(m=>points>=m.min);i=Math.max(0,i);const current=MILESTONES[i];const next=MILESTONES[i+1];const ratio=next?Math.max(2,Math.min(100,((points-current.min)/(next.min-current.min))*100)):100;return{current,next,ratio}}
function rewardsPanel(){const {current,next,ratio}=level();const points=score();const earned=earnedUnlocks();const coming=UNLOCKS.find(u=>u.min>points);return `<section class="panel soft-panel"><div class="reward-line"><div><div class="little-label">The household's bravery jar</div><h3 style="font:700 21px Fraunces,Georgia,serif;margin:5px 0">${current.name}</h3><div class="subtle">${coming?'Next sticker: '+coming.code+' '+esc(coming.name):'The complete sticker collection is yours!'}</div></div><div class="reward-badge">${earned.length?earned[earned.length-1].code:current.emoji}</div></div><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(ratio)}"><div class="progress-fill" style="width:${ratio}%"></div></div><div class="subtle">Collect stickers for the scrapbook. No streaks, no deadlines.</div><button class="link-btn" data-action="tab" data-tab="progress">See ${earned.length?earned.length+' unlocked sticker'+(earned.length!==1?'s':''):'the sticker collection'} →</button></section>`}

function recentEntries(limit=4){if(!state.logs.length)return `<div class="subtle">No practice logged yet. The first tiny win is waiting.</div>`;return state.logs.slice(0,limit).map(l=>{const quest=QUESTS.find(q=>q.id===l.activity);const photo=l.photo_asset_id?assetUrl(l.photo_asset_id):'';return `<div class="entry"><div class="entry-icon">${photo?`<img src="${esc(photo)}" alt="Practice snapshot">`:quest?.emoji||'🐾'}</div><div style="min-width:0"><div class="entry-title">${esc(l.actor)} · ${esc(quest?.title||l.activity)}</div><div class="entry-sub">${ago(l.created_at)} · ${l.comfort==='comfy'?'Felt good ✨':l.comfort==='unsure'?'A little unsure 🌤️':'Too much — dial it down 💛'}</div></div><div class="entry-stamp">${esc(l.sticker_code||'🐾')}</div></div>`}).join('')}
function renderHome(){return `${photoHero()}${rewardsPanel()}<div class="section-heading"><h2>Pick a little adventure</h2><span class="subtle">No homework here ♡</span></div><div class="quest-grid">${QUESTS.map(q=>`<div class="quest"><button class="quest-help" data-action="help" data-id="${q.id}" aria-label="How to play ${esc(q.title)}">?</button><div class="quest-emoji">${q.emoji}</div><h3>${q.title}</h3><p>${q.short}</p><button data-action="log" data-id="${q.id}" class="link-btn" style="margin-left:-5px">Log a little win →</button></div>`).join('')}</div><div class="section-heading"><h2>Little life moments</h2></div><div class="panel"><p style="margin:0 0 10px;font-size:13px;color:var(--muted)">A loaf, a silly face, a tiny toothy smile. All worthy of the scrapbook.</p><div class="tiny-actions"><button class="pill" data-action="add-photo" data-pet="Willa">🐶 Willa</button><button class="pill" data-action="add-photo" data-pet="Oscar">🐈 Oscar</button><button class="pill" data-action="add-photo" data-pet="Dennis">🐈‍⬛ Dennis</button></div></div><div class="section-heading"><h2>Recently, in the house…</h2><button class="link-btn" data-action="tab" data-tab="progress">See more</button></div><div class="panel">${recentEntries()}</div>`}
function renderAlbum(){const pics=[...state.assets.filter(a=>a.type==='photo'&&assetUrl(a.id)),...(DEFAULT_PORTRAITS.Willa?[{id:'willa-starter',pet_name:'Willa',caption:'Willa, chief adventure officer',created_at:'2026-11-04T12:00:00Z',sticker_code:'🐾',bundled_src:DEFAULT_PORTRAITS.Willa}]:[])];return `<section class="page-intro"><div class="little-label">Willa & company</div><h2>The little scrapbook 📸</h2><p>A place for the funny, ordinary, and unexpectedly lovely moments. We have Willa’s portrait to start; add the rest of the gang as you go.</p><button class="main-btn" data-action="add-photo" data-pet="Willa">＋ Add a moment</button></section>${pics.length?`<div class="memory-grid">${pics.map(p=>{let sticker=p.sticker_code||'💖';let stickerAsset=sticker.startsWith('custom:')?assetUrl(sticker.slice(7)):null;return `<div class="memory-wrap"><div class="memory"><img class="memory-img" alt="${esc(p.pet_name||'Pet')} photo" src="${esc(p.bundled_src||assetUrl(p.id))}"><div class="memory-caption">${esc(p.caption||p.pet_name||'A little moment')}</div><div class="memory-meta">${esc(p.pet_name||'Pets')} · ${fmt(p.created_at)}</div></div><div class="memory-sticker">${stickerAsset?`<img class="custom-sticker" src="${esc(stickerAsset)}" alt="Custom sticker">`:esc(sticker)}</div></div>`}).join('')}</div>`:`<div class="empty"><div class="empty-art">📷🐾</div><h3>The first page is blank</h3><p>Add a Willa face, an Oscar pose, or a Dennis loaf to start the collection.</p></div>`}`}
function rewardShelf(){const points=score();return `<div class="section-heading"><h2>The sticker collection</h2><span class="subtle">${earnedUnlocks().length} / ${UNLOCKS.length} unlocked</span></div><div class="panel"><p class="small-note" style="margin-top:0">Each filled progress bar awards a sticker you can use on scrapbook photos and little wins.</p><div class="sticker-picks" style="gap:12px">${UNLOCKS.map(u=>{const open=points>=u.min;return `<div style="width:calc(50% - 7px);display:flex;align-items:center;gap:9px;padding:8px 0;opacity:${open?1:.5}"><span style="font-size:32px" aria-hidden="true">${open?u.code:'🔒'}</span><div><div style="font-size:12px;font-weight:800">${open?esc(u.name):'Mystery sticker'}</div><div class="subtle">${open?esc(u.note):'Unlock at '+u.min+' jar points'}</div></div></div>`}).join('')}</div></div>`}
function renderProgress(){const week=state.logs.filter(l=>Date.now()-new Date(l.created_at).getTime()<7*86400000);const calm=week.filter(l=>l.comfort==='comfy');const totals=QUESTS.map(q=>({q,count:state.logs.filter(l=>l.activity===q.id&&l.comfort==='comfy').length}));const max=Math.max(1,...totals.map(t=>t.count));return `<section class="page-intro"><div class="little-label">Quietly getting braver</div><h2>Little wins, adding up 🌿</h2><p>Not a report card. Just a way to notice which everyday moments are feeling easier for Willa.</p></section><div class="stats-grid"><div class="stat"><div class="stat-num">${state.logs.length}</div><div class="stat-label">Practice check-ins, ever</div></div><div class="stat"><div class="stat-num">${calm.length}</div><div class="stat-label">Comfortable moments this week</div></div></div><div class="section-heading"><h2>Comfortable moments</h2></div><section class="panel"><div class="bars">${totals.map(({q,count})=>`<div class="bar-row"><span>${q.emoji} ${q.category}</span><div class="bar-bg"><div class="bar-fill" style="width:${count/max*100}%"></div></div><span>${count}</span></div>`).join('')}</div><p class="small-note" style="margin-bottom:0">A hard moment is useful information, but it doesn't count as a comfortable repetition. We celebrate the humans for trying without mistaking stress for progress.</p></section>${rewardShelf()}<div class="section-heading"><h2>All the attempts</h2></div><div class="panel">${recentEntries(200)}</div>`}
function renderSettings(){const cloud=state.mode==='cloud';return `<section class="page-intro"><div class="little-label">The whole gang</div><h2>Our little world ♡</h2><p>Add photos of the actual stars of this show, and upload the stickers you already have.</p></section><div class="portrait-row">${PETS.map(p=>{const src=portraitSource(p.id);return `<div class="portrait"><div class="portrait-image">${src?`<img alt="${p.id}" src="${esc(src)}">`:p.emoji}</div><div class="portrait-name">${p.id}</div><button class="link-btn" data-action="portrait" data-pet="${p.id}">Change photo</button></div>`}).join('')}</div><section class="panel spaced"><div class="setting"><h3>🖼️ Your stickers</h3><p>Upload an existing sticker image. Transparent PNGs or WebP files look especially nice.</p><button class="secondary-btn" data-action="sticker-upload">＋ Add sticker</button><div class="sticker-picks spaced">${state.assets.filter(a=>a.type==='sticker').map(a=>`<div title="${esc(a.caption||'Sticker')}" class="sticker-pick"><img src="${esc(assetUrl(a.id))}" alt="${esc(a.caption||'Sticker')}"></div>`).join('')}</div></div><div class="setting"><h3>👥 Who's playing?</h3><p>${cloud?'Both phones use their own sign-in and share one household.':'Choose a name to try the app. For now, this data stays on this device.'}</p>${cloud?`<div class="notice">Shared household code: <strong style="letter-spacing:2px">${esc(state.household?.invite_code)}</strong><br>Give this code to the other person when they first sign in.</div><button class="secondary-btn" data-action="sign-out">Sign out</button>`:`<div class="settings-buttons"><button class="pill" data-action="actor" data-person="Hil">${state.actor==='Hil'?'✓ ':''}Hil</button><button class="pill" data-action="actor" data-person="Peter">${state.actor==='Peter'?'✓ ':''}Peter</button></div>`}</div>${!cloud?`<div class="setting"><h3>📦 Save a backup</h3><p>This preview saves on this device only. Export a JSON backup of your logs and photos before clearing browser data.</p><button class="secondary-btn" data-action="backup">Export my backup</button></div><div class="setting"><h3>☁️ Two-phone syncing</h3><p>Not connected in this preview. The package includes Supabase setup so you can both use the same household without sharing passwords.</p></div>`:''}<div class="setting"><h3>🐕 Gentle training</h3><p>Tap the ? on any adventure to learn what counts as a comfortable repetition. No prescribed schedule, no streak penalties, and no competitive scoreboard.</p><p class="small-note">If Willa is regularly distressed or attempts to escape confinement, pause that exercise and consult a veterinarian or qualified reward-based behaviour professional.</p></div></section>`}
function nav(){return `<nav class="tabbar" aria-label="Main navigation">${[['home','🏡','Home'],['album','📸','Scrapbook'],['progress','🌿','Little wins'],['settings','🐾','Our pets']].map(([id,emoji,label])=>`<button class="tab ${state.tab===id?'active':''}" data-action="tab" data-tab="${id}" aria-label="${label}" ${state.tab===id?'aria-current="page"':''}><span>${emoji}</span><span>${label}</span></button>`).join('')}</nav>`}
async function render(){await loadAssetUrls();let main={home:renderHome,album:renderAlbum,progress:renderProgress,settings:renderSettings}[state.tab]();app.innerHTML=`<div class="app-shell"><header class="top"><div><div class="top-eyebrow">THE HOUSEHOLD ADVENTURE LOG</div><div class="wordmark">Willa's Little Wins <span style="font-size:19px">✳</span></div></div><button class="profile-btn" data-action="profile">${state.actor==='Hil'?'💛':'🌿'} ${esc(state.actor)} ▾</button></header><main>${main}</main>${nav()}</div><div id="modal-root"></div>`;if(state.modal)renderModal();}
function openModal(info){state.modal=info;renderModal()}
function closeModal(){state.modal=null;document.getElementById('modal-root')?.replaceChildren()}
function customStickerOptions(){return [...STICKERS.concat(earnedUnlocks().map(u=>({id:u.code,label:u.name}))).map(s=>`<option value="${esc(s.id)}">${s.id} ${s.label}</option>`),...state.assets.filter(a=>a.type==='sticker').map(s=>`<option value="custom:${esc(s.id)}">🖼️ ${esc(s.caption||'Custom sticker')}</option>`)].join('')}
function renderModal(){const root=document.getElementById('modal-root');if(!root)return;if(!state.modal){root.replaceChildren();return}const {type,id,pet}=state.modal;const quest=QUESTS.find(q=>q.id===id);let content='';if(type==='help'&&quest){content=`<div class="little-label">A tiny how-to card</div><div class="modal-head"><h2>${quest.emoji} ${quest.title}</h2><button class="modal-close" data-action="close" aria-label="Close">×</button></div><p class="muted" style="line-height:1.5">${quest.short}</p><ol class="how-steps">${quest.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="tip"><strong>That's a win:</strong> ${esc(quest.success)}</div><div class="tip" style="background:#fce9e7;margin-top:9px"><strong>Keep it kind:</strong> ${esc(quest.guard)}</div><button class="main-btn wide spaced" data-action="log" data-id="${quest.id}">We tried this! Log a moment</button>`}else if(type==='log'&&quest){content=`<div class="little-label">A little check-in · ${esc(state.actor)}</div><div class="modal-head"><h2>${quest.emoji} ${quest.title}</h2><button class="modal-close" data-action="close" aria-label="Close">×</button></div><button data-action="help" data-id="${quest.id}" class="link-btn">What does this one involve?</button><form id="log-form" data-id="${quest.id}"><div class="field"><label for="comfort">How did Willa feel?</label><select id="comfort" name="comfort"><option value="comfy">✨ Comfy and relaxed</option><option value="unsure">🌤️ A little unsure</option><option value="hard">💛 Too hard this time</option></select></div><div class="field"><label for="note">Anything worth remembering? (optional)</label><textarea id="note" name="note" maxlength="300" placeholder="A tiny detail, not an essay…"></textarea></div><div class="field"><label for="photo">A photo? (optional)</label><input id="photo" type="file" name="photo" accept="image/*"></div><div class="field"><label for="sticker">Pick a sticker</label><select id="sticker" name="sticker">${customStickerOptions()}</select></div><div class="tip">The goal is comfort, not duration. Even a one-second success counts. Too hard? Log it anyway — that tells us what to make easier.</div><button type="submit" class="main-btn wide spaced">Save this little moment ♡</button></form>`}else if(type==='photo'){content=`<div class="little-label">A memory for the scrapbook</div><div class="modal-head"><h2>📸 A little moment</h2><button class="modal-close" data-action="close" aria-label="Close">×</button></div><form id="photo-form"><div class="field"><label for="pet">Who's in the spotlight?</label><select name="pet" id="pet">${PETS.map(p=>`<option ${p.id===pet?'selected':''}>${p.id}</option>`).join('')}</select></div><div class="field"><label for="memory-photo">Choose a photo</label><input required type="file" name="photo" id="memory-photo" accept="image/*"></div><div class="field"><label for="caption">A little caption (optional)</label><input name="caption" maxlength="100" id="caption" placeholder="The majestic loaf…"></div><div class="field"><label for="sticker">Add a sticker</label><select id="sticker" name="sticker">${customStickerOptions()}</select></div><button type="submit" class="main-btn wide">Put it in the scrapbook ♡</button></form>`}else if(type==='portrait'||type==='sticker'){content=`<div class="little-label">Make it yours</div><div class="modal-head"><h2>${type==='portrait'?`📷 ${esc(pet)}'s portrait`:'🎨 Add your own sticker'}</h2><button class="modal-close" data-action="close" aria-label="Close">×</button></div><form id="asset-form" data-type="${type}" data-pet="${esc(pet||'')}"><div class="field"><label for="asset-photo">Choose an image</label><input required type="file" id="asset-photo" name="photo" accept="image/*"></div>${type==='sticker'?'<div class="field"><label for="sticker-name">Sticker name</label><input id="sticker-name" name="caption" maxlength="40" placeholder="e.g. Judgmental Oscar"></div>':''}<button class="main-btn wide">Save image ♡</button></form>`}else if(type==='profile'){content=`<div class="modal-head"><h2>Who's here? 👋</h2><button class="modal-close" data-action="close" aria-label="Close">×</button></div>${state.mode==='cloud'?`<p>Signed in as ${esc(state.actor)}. The other human can join with the code in Our Pets.</p>`:`<div class="tiny-actions"><button class="pill" data-action="actor" data-person="Hil">${state.actor==='Hil'?'✓ ':''}💛 Hil</button><button class="pill" data-action="actor" data-person="Peter">${state.actor==='Peter'?'✓ ':''}🌿 Peter</button></div><p class="small-note">The local preview lets you try both profiles. Cloud sync later gives each of you your own sign-in.</p>`}`}
root.innerHTML=`<div class="modal-back" data-action="backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="Willa's Little Wins dialog">${content}</div></div>`;root.querySelector('.modal')?.scrollTo(0,0)}
function toast(message){document.querySelector('.toast')?.remove();const node=document.createElement('div');node.className='toast';node.textContent=message;document.body.append(node);setTimeout(()=>node.remove(),3700)}
async function resizeImage(file,isSticker=false){return new Promise((resolve,reject)=>{const img=new Image;const object=URL.createObjectURL(file);img.onload=()=>{try{const max=isSticker?450:1000;const ratio=Math.min(1,max/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{URL.revokeObjectURL(object);if(!blob)reject(Error('Unable to process image'));else resolve(blob)},isSticker?'image/png':'image/jpeg',.78)}catch(e){URL.revokeObjectURL(object);reject(e)}};img.onerror=()=>{URL.revokeObjectURL(object);reject(Error('Could not read image'))};img.src=object})}
async function saveAsset({file,type,pet_name,caption='',sticker_code=''}){const blob=await resizeImage(file,type==='sticker');const asset={id:uid(),type,pet_name,caption,sticker_code,created_by_name:state.actor,created_at:new Date().toISOString()};if(state.mode==='local'){await blobPut(asset.id,blob);state.assets.unshift(asset);persistLocal()}else{const ext=type==='sticker'?'png':'jpg';const path=state.household.id+'/'+asset.id+'.'+ext;const result=await state.supabase.storage.from('pet_media').upload(path,blob,{contentType:blob.type,upsert:false});if(result.error)throw result.error;const row={...asset,household_id:state.household.id,path,created_by:state.user.id};const added=await state.supabase.from('assets').insert(row);if(added.error){await state.supabase.storage.from('pet_media').remove([path]);throw added.error}state.assets.unshift(row)}return asset.id}
async function saveLog({id,comfort,note,photoFile,sticker_code}){let photo_asset_id=null;if(photoFile)photo_asset_id=await saveAsset({file:photoFile,type:'photo',pet_name:'Willa',caption:note||QUESTS.find(q=>q.id===id)?.title||'Little win',sticker_code});const entry={id:uid(),activity:id,comfort,note,photo_asset_id,sticker_code,actor:state.actor,created_at:new Date().toISOString()};if(state.mode==='local'){state.logs.unshift(entry);persistLocal()}else{const result=await state.supabase.from('entries').insert({...entry,household_id:state.household.id,user_id:state.user.id});if(result.error)throw result.error;state.logs.unshift(entry)}}
async function exportBackup(){const out={app:'Willa Little Wins',version:1,date:new Date().toISOString(),logs:state.logs,assets:[]};for(const a of state.assets){const blob=await blobGet(a.id);let base64='';if(blob)base64=await new Promise((res,rej)=>{const fr=new FileReader;fr.onload=()=>res(fr.result);fr.onerror=()=>rej(fr.error);fr.readAsDataURL(blob)});out.assets.push({...a,data_url:base64})}const data=new Blob([JSON.stringify(out)],{type:'application/json'});const url=URL.createObjectURL(data);const anchor=document.createElement('a');anchor.href=url;anchor.download='willa-little-wins-backup-'+new Date().toISOString().slice(0,10)+'.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),12000)}
async function clickAction(event){const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='backdrop'&&event.target===b){closeModal();return}if(a==='close'){closeModal();return}if(a==='tab'){state.tab=b.dataset.tab;state.modal=null;await render();window.scrollTo(0,0);return}if(a==='help'){openModal({type:'help',id:b.dataset.id});return}if(a==='log'){openModal({type:'log',id:b.dataset.id});return}if(a==='add-photo'){openModal({type:'photo',pet:b.dataset.pet||'Willa'});return}if(a==='portrait'){openModal({type:'portrait',pet:b.dataset.pet});return}if(a==='sticker-upload'){openModal({type:'sticker'});return}if(a==='profile'){openModal({type:'profile'});return}if(a==='actor'&&state.mode==='local'){state.actor=b.dataset.person;localStorage.setItem('willa-actor',state.actor);closeModal();await render();toast(`Hi, ${state.actor} ♡`);return}if(a==='backup'){try{await exportBackup();toast('Backup downloaded ♡')}catch(e){toast(e.message)}return}if(a==='sign-out'&&state.mode==='cloud'){await state.supabase.auth.signOut();return}}
async function submitAction(event){if(!['auth-form','join-form','log-form','photo-form','asset-form'].includes(event.target.id))return;event.preventDefault();const form=event.target;const fd=new FormData(form);const btn=form.querySelector('button[type="submit"],button.main-btn');if(btn){btn.disabled=true;btn.textContent='Saving…'}try{switch(form.id){case 'auth-form':{const email=String(fd.get('email'));const result=await state.supabase.auth.signInWithOtp({email,options:{emailRedirectTo:window.location.href.split('#')[0]}});if(result.error)throw result.error;renderAuth('Check your email for a sign-in link.');return}case 'join-form':{const name=String(fd.get('display_name'));const code=String(fd.get('invite_code')||'').trim().toLowerCase();const fn=code?'join_household':'create_household';const args=code?{p_code:code,p_display_name:name}:{p_name:'Willa’s Little Wins',p_display_name:name};const result=await state.supabase.rpc(fn,args);if(result.error)throw result.error;await loadMembership();return}case 'log-form':{const before=score();const file=fd.get('photo');await saveLog({id:form.dataset.id,comfort:String(fd.get('comfort')),note:String(fd.get('note')||''),photoFile:file instanceof File&&file.size?file:null,sticker_code:String(fd.get('sticker')||'⭐')});closeModal();await render();const prize=newlyEarned(before,score());toast(prize?'New sticker unlocked: '+prize.name+'!':'A little moment saved 🐾');break}case 'photo-form':{const before=score();const file=fd.get('photo');if(!(file instanceof File)||!file.size)throw Error('Please choose a photo');await saveAsset({file,type:'photo',pet_name:String(fd.get('pet')),caption:String(fd.get('caption')||''),sticker_code:String(fd.get('sticker')||'💖')});state.tab='album';closeModal();await render();const prize=newlyEarned(before,score());toast(prize?'New sticker unlocked: '+prize.name+'!':'Added to the scrapbook 💖');break}case 'asset-form':{const file=fd.get('photo');if(!(file instanceof File)||!file.size)throw Error('Please choose an image');await saveAsset({file,type:form.dataset.type==='portrait'?'portrait':'sticker',pet_name:form.dataset.pet||'',caption:String(fd.get('caption')||'')});closeModal();await render();toast('Looking adorable ♡');break}}}catch(e){toast('Could not save: '+e.message);if(btn){btn.disabled=false;btn.textContent='Try again'}}}
document.addEventListener('click',e=>{clickAction(e).catch(err=>toast(err.message))});document.addEventListener('submit',e=>{submitAction(e).catch(err=>toast(err.message))});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
maybeInitCloud();
if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});